/*
 * Focused logic test for CVE-2013-6367 guard in KVM apic_get_tmcct().
 *
 * Models the security-relevant control flow of arch/x86/kvm/lapic.c:
 *   if (APIC_TMICT == 0) return 0;
 *   patched: if (period == 0) return 0;
 *   ns = mod(remaining, period); tmct = ns / (BUS * divide_count);
 *
 * patched=0 reproduces the vulnerable pre-fix condition; patched=1 the fix.
 * A zero period therefore reaches an integer modulo by zero, which raises
 * SIGFPE exactly like the kernel's do_div/mod_64 divide-by-zero.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <sys/wait.h>

static uint32_t tmcct(uint32_t tmict, int64_t period, int patched)
{
	/* original existing guard */
	if (tmict == 0)
		return 0;
	/* CVE-2013-6367 fix guard */
	if (patched && period == 0)
		return 0;
	/* dangerous operation: modulo by period (0 => SIGFPE) */
	volatile int64_t p = period;
	int64_t ns = 12345 % p;
	return (uint32_t)(ns / 1);
}

static int run_case(const char *name, uint32_t tmict, int64_t period, int patched,
		    int expect_sigfpe, uint32_t expect_val)
{
	pid_t pid = fork();
	if (pid == 0) {
		uint32_t v = tmcct(tmict, period, patched);
		/* communicate value via exit code (values are small here) */
		_exit((int)(v & 0x7f));
	}
	int status;
	waitpid(pid, &status, 0);
	if (expect_sigfpe) {
		if (WIFSIGNALED(status) && WTERMSIG(status) == SIGFPE) {
			printf("PASS %-42s -> SIGFPE (divide by zero) as expected\n", name);
			return 0;
		}
		printf("FAIL %-42s -> expected SIGFPE, got status=0x%x\n", name, status);
		return 1;
	}
	if (WIFSIGNALED(status)) {
		printf("FAIL %-42s -> unexpected signal %d\n", name, WTERMSIG(status));
		return 1;
	}
	uint32_t got = (uint32_t)WEXITSTATUS(status);
	if (got == expect_val) {
		printf("PASS %-42s -> %u (no fault)\n", name, got);
		return 0;
	}
	printf("FAIL %-42s -> got %u expected %u\n", name, got, expect_val);
	return 1;
}

int main(void)
{
	int rc = 0;
	/* Negative path: pre-fix code with TMICT!=0 and period==0 divides by zero */
	rc |= run_case("prefix TMICT=5 period=0 (vulnerable)", 5, 0, 0, 1, 0);
	/* Negative path closed: patched code returns 0 before dividing */
	rc |= run_case("patched TMICT=5 period=0 (fixed)", 5, 0, 1, 0, 0);
	/* Positive path: normal nonzero period still computes */
	rc |= run_case("patched TMICT=5 period=100 (normal)", 5, 100, 1, 0, 23);
	/* Original existing guard still short-circuits */
	rc |= run_case("patched TMICT=0 period=0 (existing guard)", 0, 0, 1, 0, 0);
	printf("RESULT: %s\n", rc == 0 ? "ALL PASS" : "FAILURES");
	return rc;
}

